def sha(raw):return hashlib.sha256(raw).hexdigest()
def git(raw):return hashlib.sha1(b"blob "+str(len(raw)).encode()+b"\0"+raw).hexdigest()
def js(value):return(json.dumps(value,ensure_ascii=False,sort_keys=True,indent=2,allow_nan=False)+"\n").encode()
def state(st):return(st.st_dev,st.st_ino,st.st_mode,st.st_nlink,st.st_uid,st.st_gid,st.st_size,st.st_mtime_ns,st.st_ctime_ns)
def pinned(path,size,digest):
 fd=os.open(path,os.O_RDONLY|os.O_NOFOLLOW)
 try:
  before=os.fstat(fd);assert stat.S_ISREG(before.st_mode)and before.st_nlink==1 and before.st_size==size
  with os.fdopen(os.dup(fd),"rb")as stream:raw=stream.read(size+1)
  assert state(before)==state(os.fstat(fd))==state(os.lstat(path))
 finally:os.close(fd)
 assert len(raw)==size and sha(raw)==digest
 return raw
def write(path,raw):
 path.parent.mkdir(parents=True,exist_ok=True,mode=0o700)
 fd=os.open(path,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o600)
 with os.fdopen(fd,"wb")as stream:stream.write(raw);stream.flush();os.fsync(stream.fileno())
 assert pinned(path,len(raw),sha(raw))==raw
 return{"bytes":len(raw),"sha256":sha(raw),"git_blob_sha1":git(raw)}
def main():
 ap=argparse.ArgumentParser(description=__doc__);ap.add_argument("--base-package",type=Path,required=True);ap.add_argument("--out",type=Path,required=True)
 args=ap.parse_args();base=args.base_package.resolve();out=args.out;assert out.is_absolute()and out.parent.resolve()==out.parent
 os.umask(0o077)
 pinraw=pinned(base/"CANDIDATE-PINS.json",8729,BASE_PINS_SHA);pins=json.loads(pinraw);allraw={}
 for row in pins["files"]:allraw[row["path"]]=pinned(base/row["path"],row["bytes"],row["sha256"])
 original={Path(k).name:v for k,v in allraw.items()if k.startswith("reference/production/")}
 prior={Path(k).name:v for k,v in allraw.items()if k.startswith("candidate/source/")}
 assert len(original)==len(prior)==15 and set(original)==set(prior)
 candidate=dict(prior);inverses={}
 for name,replacements in TRANSFORMS.items():
  text=prior[name].decode()
  for replacement in replacements:
   old,new=replacement[:2];count=replacement[2]if len(replacement)>2 else 1
   assert text.count(old)==count,(name,"old replacement count");text=text.replace(old,new)
  candidate[name]=text.encode()
  for replacement in reversed(replacements):
   old,new=replacement[:2];count=replacement[2]if len(replacement)>2 else 1
   assert text.count(new)==count,(name,"inverse replacement count");text=text.replace(new,old)
  assert text.encode()==prior[name];inverses[name]=True
 daily=prior["daily_phone_local.py"].decode()
 for name in sorted(TRANSFORMS):
  oldhash=sha(prior[name]);assert daily.count(oldhash)==1;daily=daily.replace(oldhash,sha(candidate[name]))
 candidate["daily_phone_local.py"]=daily.encode()
